// n8n Code node ("Listener watchdog") -- mode: Run Once for All Items
// Runs every 5 minutes. If listener.py has not sent a heartbeat for DOWN_MIN minutes,
// send ONE warning (not one every 5 minutes). The "back online" message comes from
// "Format market alert" when the next heartbeat arrives.

// ============ SETTINGS (edit these) ============
const DOWN_MIN = 15;
// ===============================================

const store = $getWorkflowStaticData('global');
const last = store.listenerLastSeen || 0;
if (!last) return [];                       // never heard from it yet: nothing to compare

const ageMin = Math.round((Date.now() - last) / 60000);
if (ageMin >= DOWN_MIN && !store.listenerDownAlerted) {
  store.listenerDownAlerted = true;
  return [{ json: {
    text: `\ud83d\udd0c <b>Listener is down</b>\nNo heartbeat for ${ageMin} min. Price-spike, liquidation and funding alerts are NOT running. Check that your PC is on, awake and online.`,
    severity: 4,
  } }];
}
return [];
